INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch06$PT132-S4-Q21$batch06$, 132, 4, 21, $batch06$Method of Reasoning$batch06$, $batch06$It is virtually certain that the government contract for building the new highway will be awarded to either Phoenix Contracting or Cartwright Company. I have just learned that the government has decided not to award the contract to Cartwright Company. It is therefore almost inevitable that Phoenix Contracting will be awarded the contract.$batch06$, $batch06$The argument proceeds by$batch06$, $batch06$A$batch06$, true, $batch06$Batch 06; question text from local bank.$batch06$ FROM lr_sections s WHERE s.preptest=132 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch06$PT132-S4-Q21$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$A$batch06$, $batch06$concluding that it is extremely likely that an event will occur by ruling out the only probable alternative$batch06$, $batch06$Correct$batch06$, true FROM lr_questions q WHERE q.qid=$batch06$PT132-S4-Q21$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$A$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$B$batch06$, $batch06$inferring, from a claim that one of two possible events will occur, that the other event will not occur$batch06$, $batch06$Bad Description$batch06$, false FROM lr_questions q WHERE q.qid=$batch06$PT132-S4-Q21$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$B$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$C$batch06$, $batch06$refuting a claim that a particular event is inevitable by establishing the possibility of an alternative event$batch06$, $batch06$Opposite$batch06$, false FROM lr_questions q WHERE q.qid=$batch06$PT132-S4-Q21$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$C$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$D$batch06$, $batch06$predicting a future event on the basis of an established pattern of past events$batch06$, $batch06$Bad Description$batch06$, false FROM lr_questions q WHERE q.qid=$batch06$PT132-S4-Q21$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$D$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$E$batch06$, $batch06$inferring a claim about the probability of a particular event from a general statistical statement$batch06$, $batch06$Bad Description$batch06$, false FROM lr_questions q WHERE q.qid=$batch06$PT132-S4-Q21$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$E$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch06$PT132-S4-Q21$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch06$Conclusion$batch06$, $batch06$Phoenix Contracting will almost certainly get the contract.$batch06$), (1, $batch06$Evidence$batch06$, $batch06$The contract will almost certainly go to Phoenix or Cartwright, and the government has decided against Cartwright.$batch06$), (2, $batch06$Evaluate$batch06$, $batch06$Two realistic candidates; one is ruled out. The other is left as the near-certain winner. That is elimination, and the strength words matter: "virtually certain" in the premise becomes "almost inevitable" in the conclusion, never "definitely."$batch06$), (3, $batch06$Goal$batch06$, $batch06$Concluding something is extremely likely by ruling out the only probable alternative.$batch06$)) v(position,label,body) WHERE q.qid=$batch06$PT132-S4-Q21$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch06$A$batch06$, $batch06$"Extremely likely" matches "almost inevitable." "The only probable alternative" is Cartwright. Both halves fit.$batch06$), ($batch06$B$batch06$, $batch06$This reverses the direction. The argument reasons from one event *not* happening (Cartwright) to the other happening, not the other way around.$batch06$), ($batch06$C$batch06$, $batch06$The argument establishes that something is nearly inevitable. It refutes nothing.$batch06$), ($batch06$D$batch06$, $batch06$No pattern of past events is used.$batch06$), ($batch06$E$batch06$, $batch06$No general statistics are cited.$batch06$)) v(letter,body) WHERE q.qid=$batch06$PT132-S4-Q21$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
